    58  {
    59    /* both patterns are empty or contain wildcards => overlap */
    60    if ((strcmp(p1, "") == 0 || strcmp(p1, "*") == 0) &&
    61        (strcmp(p2, "") == 0 || strcmp(p2, "*") == 0))
    62      return 1;
    63    /* Either pattern is empty (but the other is not empty or wildcard only) => no overlap */
    64    if (strcmp (p1, "") == 0 || strcmp(p2, "") == 0)
    65      return 0;
    66    if ((p1[0] == '*' || p2[0] == '*') && (wildcard_wildcard_match (p1,p2+1) || wildcard_wildcard_match (p1+1,p2)))
    67      return 1;
    68    if ((p1[0] == '?' || p2[0] == '?' || p1[0] == p2[0]) && wildcard_wildcard_match (p1+1,p2+1))
    69      return 1;
    70    /* else, no match, return false */
    71    return 0;
